import type { Column, Typed } from '../Column'
import type { Record } from '../Record'

// TODO: Currently just constraining to any record on a table with name "domain", but this means we don't know
// anything about the record's data. We should constrain to the domain table itself but this creates a circular
// relationship between the domain table and domain ID columns (since the domain table has its own domain ID
// column).
/**
 * A Column for a domain ID type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @param config - an object that can include all base `Column` properties
 */
export function DomainIdColumn<
    const Type extends Record<'domain'> | 'global',
    const Default extends Type,
    const C extends Column<Type, Default>,
>(config: C & Column<Type, Default>) {
    return config as Typed<Type, C>
}
